import { CardListWrapper } from './index.style'
import PackageDetailCard from './packageDetailCard'
import {
  useGetEwDetails,
  useGetPackages, useUpdateExtendedWarrantyDraft
} from '../../../../state/hooks/useExtendedWarrantyState'
import { useCallback, useEffect, useMemo, useState } from 'react'
import Container from '../../../../../../../components/Container'
import {
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
  useResetError
} from '@pasarpolis/common-react-hooks'
import { useHistory, useParams } from 'react-router'
import { get } from 'lodash'
import PolicyStepsHeader from '../../../../../../../components/PolicyStepsHeader'
import { STEPS } from '../../../../constant'
import PackageNotFound from '../../../../../Packages/components/PackageNotFound'

const PackageList = () => {
  const { id } = useParams()
  const history = useHistory()
  const { resetError } = useResetError()
  const [{ getPackagesData = {} }, getPackagesRequest] = useGetPackages()
  const [
    { GET_PACKAGES_LOADER },
    dispatchLoader
  ] = useLoaderContextValue()
  const [
    { getEwDetailsData = {} },
    getEwDetailsRequest
  ] = useGetEwDetails()

  const [, updateExtendedWarrantyDraftRequest] = useUpdateExtendedWarrantyDraft()
  const [{ updateExtendedWarrantyDraftStatus }] = useErrorContextValue()
  const [policyDetail, setPolicyDetail] = useState({})
  const [draftLoader, setDraftLoader] = useState(false)

  const getInitialPackages = useCallback(() => {
    if (Object.keys(getEwDetailsData).length) {
      setPolicyDetail(getEwDetailsData)
      const payload = {
        purchase_type: 'new-purchase',
        vehicle_type: get(getEwDetailsData.policy_details, 'vehicle_type'),
        brand: get(getEwDetailsData.policy_details, 'brand'),
        variant: get(getEwDetailsData.policy_details.model_data, 'model_name'),
        variant_code: get(getEwDetailsData.policy_details.model_data, 'variant_code'),
        year: get(getEwDetailsData.policy_details, 'year'),
        model: get(getEwDetailsData.policy_details.model_data, 'model_code'),
        vehicle_sum_insured: get(getEwDetailsData.policy_details, 'vehicle_sum_insured'),
        usage: get(getEwDetailsData.policy_details, 'usage'),
        start_date: get(getEwDetailsData.policy_details, 'start_date'),
        category_name: get(getEwDetailsData.policy_details.model_data, 'category_name'),
        code: 'extended-warranty-protection',
        sort: 'PRICE_HI-TO-LOW'
      }

      getPackagesRequest({
        body: {
          ...payload
        }
      })
    }
  }, [getPackagesRequest, getEwDetailsData])

  useEffect(() => {
    if (id) {
      getEwDetailsRequest({ draftQuoteId: id })
    }
  }, [getEwDetailsRequest, id])

  const isPkgsEmpty = useMemo(() => {
    if (getPackagesData['error-code']) {
      return true
    }
    return !getPackagesData?.complete_match?.length
  }, [getPackagesData])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_PACKAGES_LOADER: undefined
        })
      )
    }
  }, [dispatchLoader])

  useEffect(() => {
    getInitialPackages()
  }, [getInitialPackages])

  useEffect(() => {
    resetError(['updateTravelDraftStatus'])
    if (updateExtendedWarrantyDraftStatus === 'success') {
      setDraftLoader(false)
      history.push({
        pathname: `/extended_warranty/package_detail/${id}`,
        state: {
          activeTab: 0
        }
      })
    }
  }, [updateExtendedWarrantyDraftStatus, resetError])

  const handleBackClick = () => {
    history.push({
      pathname: '/extended_warranty',
    })
  }

  const handlePackageClick = (code) => {
    setDraftLoader(true)
    updateExtendedWarrantyDraftRequest({
      body: {
        section: 'package_insurance',
        sub_section: 'package_list',
        data: {
          ...policyDetail.policy_details,
          package_code: code,
          package_type: code
        }
      },
      draftQuoteId: id
    })
  }

  return (
    <Container
      title='Extended Warranty'
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      displayBackButton
      hideBottomTabs
      loader={
        GET_PACKAGES_LOADER || draftLoader
      }
      onBackClick={handleBackClick}
    >
      <PolicyStepsHeader
        stepsData={STEPS}
        activeCount={2}
        prevActive={{
          1: true
        }}
      />
      {(GET_PACKAGES_LOADER === false) && !isPkgsEmpty && (
        <>
          {
            !!(getPackagesData?.complete_match.length > 0) && (
              <CardListWrapper>
                {getPackagesData?.complete_match?.map((pack) => {
                  return (
                    <PackageDetailCard
                      props={pack}
                      handlePackageClick={handlePackageClick}
                    />
                  )
                })}
              </CardListWrapper>
            )
          }
        </>
      )}
      {
        (GET_PACKAGES_LOADER === false) && isPkgsEmpty && (
          <PackageNotFound history={history} showProductBtn={false} />
        )
      }
    </Container>
  )
}

export default PackageList
