import { useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import {
  useErrorContextValue,
  useLoaderContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { Button, CustomText } from '../../../components'
import DynamicForm from '../../../components/DynamicForm'
import BottomActionSheet from '../../../components/BottomActionSheet'
import ShowSnackbar from '../../../components/ShowNotification'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { MV_RENEWAL_FLOW } from '../../../constants/pkgCode'
import {
  ICON_UPLOAD_POLICY,
  LOGO_AUS,
  LOGO_SAHABAT,
  LOGO_SEA_INSURE,
  LOGO_SINARMAS,
} from '../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../lang/index'
import {
  useGetMvRenewalDetails,
  usePostMvRenewalPolicyOcr,
} from '../../../containers/Private/Policy/state/hooks/usePolicyState'
import { usePolicyContextValue } from '../../../containers/Private/Policy/context'
import { ContentContainer, IconContainer, FormWrapper } from '../container/index.style'
import { INPUT_FILE_TYPE } from '../../../constants/file'

const DOCUMENT_UPLOAD_FORM = ({ formState, isUploading }) => [
  {
    type: 'radioV2',
    title: '',
    name: 'provider',
    required: true,
    disabled: isUploading,
    data: {
      variant: 'outlined',
      options: [
        { value: 'aus', label: 'AUS', icon: LOGO_AUS, iconSize: 'lg' },
        { value: 'sinarmas', label: 'Sinarmas', icon: LOGO_SINARMAS, iconSize: 'lg' },
        { value: 'bess', label: 'Sahabat', icon: LOGO_SAHABAT, iconSize: 'lg' },
        { value: 'mega-pratama', label: 'Sea Insure', icon: LOGO_SEA_INSURE, iconSize: 'lg' },
      ],
    },
  },
  {
    type: 'uploadFileV3',
    name: 'policy_document',
    title: LANG_STRINGS.uploadEnglishDocument,
    required: true,
    disabled: !formState?.provider || isUploading,
    data: {
      fileType: INPUT_FILE_TYPE.PDF,
      isDirectUpload: true,
    },
  },
]

function DocumentUpload({
  show,
  onClose,
  onClickSkip,
  onClickBack,
  onVehicleDataFound,
  onVehicleDataNotFound,
}) {
  const formRef = useRef()
  const [formState, setFormState] = useState({})
  const [isSubmitDisabled, setIsSubmitDisabled] = useState(true)

  const [{ postMvRenewalPolicyOcrData }, postMvRenewalPolicyOcrRequest] =
    usePostMvRenewalPolicyOcr()
  const [{ getMvRenewalDetailsData }, getMvRenewalDetailsRequest] = useGetMvRenewalDetails()
  const [, , dispatchSetPolicyState] = usePolicyContextValue()
  const [{ POST_MV_RENEWAL_POLICY_OCR_LOADER }] = useLoaderContextValue()
  const [{ postMvRenewalPolicyOcrStatus, getMvRenewalDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const isUploading = !!POST_MV_RENEWAL_POLICY_OCR_LOADER

  const handleChangeFormData = (newData) => {
    const _formState = { ...formState, ...newData }
    setFormState(_formState)
    if (!!_formState.provider && !!_formState.policy_document) {
      setIsSubmitDisabled(false)
    } else {
      setIsSubmitDisabled(true)
    }
  }

  const handleClickUpload = () => {
    if (!formRef.current?.validateFormValues()) return

    const formData = new FormData()
    formData.append('provider', formState.provider)
    formData.append('file', formState.policy_document)
    postMvRenewalPolicyOcrRequest({ body: formData })
  }

  useEffect(() => {
    if (!postMvRenewalPolicyOcrStatus) return
    if (postMvRenewalPolicyOcrStatus === 'success' && !!postMvRenewalPolicyOcrData) {
      // On OCR success, check for chasis_number again
      getMvRenewalDetailsRequest({
        query: {
          chasis_number: postMvRenewalPolicyOcrData.chasis_number,
          flow: MV_RENEWAL_FLOW.EXISTING_CAR,
        },
      })
    } else {
      ShowSnackbar.error({ text: ERROR_LANG.renewalsOcrError })
      dispatchSetPolicyState({ postMvRenewalPolicyOcrData: null })
      resetError(['postMvRenewalPolicyOcrStatus'])
    }
  }, [
    resetError,
    dispatchSetPolicyState,
    postMvRenewalPolicyOcrStatus,
    postMvRenewalPolicyOcrData,
    getMvRenewalDetailsRequest,
  ])

  useEffect(() => {
    if (!getMvRenewalDetailsStatus) return
    if (getMvRenewalDetailsStatus === 'success' && !!getMvRenewalDetailsData?.data) {
      // If chasis_number exist, start process as a renewal
      ShowSnackbar.success({ text: ERROR_LANG.generalSuccessPleaseContinue })
      onVehicleDataFound(getMvRenewalDetailsData?.data)
    } else {
      // If not, start process as a new purchase with prefilled data
      ShowSnackbar.success({ text: ERROR_LANG.generalSuccessPleaseContinue })
      onVehicleDataNotFound(postMvRenewalPolicyOcrData)
    }
    dispatchSetPolicyState({ postMvRenewalPolicyOcrData: null, getMvRenewalDetailsData: null })
    resetError(['postMvRenewalPolicyOcrStatus', 'getMvRenewalDetailsStatus'])
  }, [
    resetError,
    dispatchSetPolicyState,
    getMvRenewalDetailsStatus,
    getMvRenewalDetailsData,
    postMvRenewalPolicyOcrData,
    onVehicleDataFound,
    onVehicleDataNotFound,
  ])

  return createPortal(
    <BottomActionSheet onCloseSheet={onClose} show={show} zIndex={5} showHeader>
      <ContentContainer>
        <IconContainer>
          <img src={ICON_UPLOAD_POLICY} alt="" />
        </IconContainer>
        <CustomText
          color={AgentColorPallette.darkCharcoal}
          size="0.9em"
          weight={800}
          textAlign="center"
          marginBottom="8px"
        >
          {LANG_STRINGS.uploadPolicyDocument}
        </CustomText>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size="0.8em"
          weight={600}
          textAlign="center"
          marginBottom="8px"
        >
          {LANG_STRINGS.renewalsOcrUploadDocument}
        </CustomText>
        <CustomText
          color={AgentColorPallette.darkCharcoal}
          size="0.8em"
          weight={800}
          textAlign="center"
          marginBottom="16px"
        >
          {LANG_STRINGS.renewalsOcrAcceptedDocument}
        </CustomText>

        <FormWrapper>
          <DynamicForm
            ref={formRef}
            formName="chasis-number-input"
            form={DOCUMENT_UPLOAD_FORM({ formState, isUploading })}
            onChange={handleChangeFormData}
          />
        </FormWrapper>

        <Button
          variant="filled"
          loading={isUploading}
          disabled={isSubmitDisabled}
          handleClick={handleClickUpload}
          style={{ marginBottom: 8 }}
        >
          {LANG_STRINGS.uploadEnglish}
        </Button>
        <Button variant="outlined" handleClick={onClickSkip} style={{ marginBottom: 8 }}>
          {LANG_STRINGS.skip2}
        </Button>
        <Button variant="outlined" handleClick={onClickBack}>
          {LANG_STRINGS.return}
        </Button>
      </ContentContainer>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default DocumentUpload
