import {
  CardWrapper,
  CardHeaderCtn,
  CardHeading2,
  CardHeading,
  CardDetailsCtn,
  PriceDetails,
  CardDetailsHeaderCtn,
  ImageCtn,
  CardCtn
} from './index.style'
import { useCallback, useMemo } from 'react'
import { formatMoney } from '../../../../../../../helpers/utility'
import { get } from 'lodash'

const PackageDetailCard = ({ props, handlePackageClick = () => {} }) => {
  const packageData = useMemo(() => {
    return {
        providerName: get(props, 'provider.name', ''),
        packageCode: get(props, 'package.code', ''),
        packageName: get(props, 'package.name', ''),
        premiumAmount: get(props, 'premium.amount', 0),
        premiumAmount2: get(props, 'basic_premium', 0),
        cancellationBenifit: get(props, 'cancellation_benifit', ''),
        medicalBenifit: get(props, 'medical_benifit', ''),
        lostBaggageBenifit: get(props, 'lost_baggage_benifit', ''),
        commissionPercent: get(props, 'commission_rate', 0),
        commissionAmount: get(props, 'commission', 0),
        sumInsured: get(props, 'total_sum_insured', 0),
        points: get(props, 'points', 0),
    }
  }, [props])

  const renderCardDetails = useCallback((text, amount) => {
    return (
      <CardDetailsCtn>
        <PriceDetails>{text}</PriceDetails>
        <PriceDetails>{amount}</PriceDetails>
      </CardDetailsCtn>
    )
  }, [])

  const renderHeadingDetails = useCallback((text, amount, textAlign) => {
    return (
      <CardCtn textAlign={textAlign}>
        <CardHeading>{text}</CardHeading>
        <CardHeading2>{amount}</CardHeading2>
      </CardCtn>
    )
  }, [])

  return (
    <CardWrapper onClick={() => handlePackageClick(props.code)}>
      <CardHeaderCtn>
        <ImageCtn>
          {props?.provider?.logo_url && <img
            src={props?.provider?.logo_url}
            width={48}
            height={48}
            alt='logo'
            lassName='logo-image'
          />}
        </ImageCtn>
        <CardHeading textAlign="center">{packageData.providerName}</CardHeading>
        {
            (packageData.packageCode === 'extended-warranty-protection-bronze' &&
                <CardHeading2 textAlign="center" color="#C86400">{packageData.packageName}</CardHeading2>)
        }
        {
            (packageData.packageCode === 'extended-warranty-protection-silver' &&
                <CardHeading2 textAlign="center" color="#666666">{packageData.packageName}</CardHeading2>)
        }
        {
            (packageData.packageCode === 'extended-warranty-protection-gold' &&
                <CardHeading2 textAlign="center" color="#B4A000">{packageData.packageName}</CardHeading2>)
        }       
      </CardHeaderCtn>
      <CardDetailsHeaderCtn>
        {renderHeadingDetails('PREMI / 12 Bulan', formatMoney((packageData.premiumAmount || packageData.premiumAmount2), 0, 'Rp'), 'left')}
        {renderHeadingDetails(
          'Nilai Pertanggungan',
          formatMoney(packageData.sumInsured, 0, 'Rp'),
          'right'
        )}
      </CardDetailsHeaderCtn>
      {renderCardDetails(
        'Poin Didapat',
        // `Poin ${packageData.points}`
        formatMoney(packageData.points, 0, 'Poin')
      )}
    </CardWrapper>
  )
}

export default PackageDetailCard
